local config = {
  ui_story_30960401_1_dialog_content = "Hello.",
  ui_story_30960401_2_dialog_content = "Hello there, Sariel. What can I do for—",
  ui_story_30960401_3_dialog_content = "Stand a little to the left.",
  ui_story_30960401_4_dialog_content = "What?",
  ui_story_30960401_5_dialog_content = "Take a step to the left... You're off-center from the wall behind you.",
  ui_story_30960401_6_dialog_content = "...?",
  ui_story_30960401_7_dialog_content = "*Step to the left*",
  ui_story_30960401_8_dialog_content = "Hmm... That's much better.",
  ui_story_30960401_9_dialog_content = "So, <color=#FFB400>Gabriel</color>...",
  ui_story_30960401_10_dialog_content = "I'm PlayerName...",
  ui_story_30960401_11_dialog_content = "I know. I just wanted to ask if you know where Gabriel is.",
  ui_story_30960401_12_dialog_content = "You called me to come over here, but you're actually looking for someone else...",
  ui_story_30960401_13_dialog_content = "You could've just asked me via the terminal...",
  ui_story_30960401_14_dialog_content = "I forgot.",
  ui_story_30960401_15_dialog_content = "...",
  ui_story_30960401_16_option_content = "I've assigned Gabriel on duty.",
  ui_story_30960401_17_dialog_content = "Hmm... Is that so...?",
  ui_story_30960401_18_dialog_content = "You look disappointed... Is there something wrong?",
  ui_story_30960401_19_dialog_content = "When will she be back?",
  ui_story_30960401_20_dialog_content = "If she isn't taking a sneaky nap outside, she should be back in around six hours.",
  ui_story_30960401_21_dialog_content = "That's no way to boost employee morale...",
  ui_story_30960401_22_dialog_content = "I heard that, Sariel...",
  ui_story_30960401_23_option_content = "Gabriel hasn't joined yet.",
  ui_story_30960401_24_dialog_content = "Sorry, but Gabriel isn't part of my team yet. You're talking about the Angel of Lumopolis, right...?",
  ui_story_30960401_25_dialog_content = "That's too bad.",
  ui_story_30960401_26_dialog_content = "It's not all bad. I mean... I have you by my side, right?",
  ui_story_30960401_27_dialog_content = "I mean, that's too bad for me...",
  ui_story_30960401_28_dialog_content = "I only came here because I heard you got a lot of Aurorians from Lumopolis.",
  ui_story_30960401_29_dialog_content = "What's with the sudden attitude?",
  ui_story_30960401_30_dialog_content = "Forget it. Basically—",
  ui_story_30960401_31_dialog_content = "Do you have any cash on you?",
  ui_story_30960401_32_dialog_content = "Whoa... Where did that come from!? Wait a minute... What do you want, exactly?",
  ui_story_30960401_33_dialog_content = "Lend me some money. That's it.",
  ui_story_30960401_34_dialog_content = "\"That's it\"!? It sounds like you've already decided I'm giving it to you...",
  ui_story_30960401_35_dialog_content = "It's urgent, really... I can't really say why, but I just need some money.",
  ui_story_30960401_36_dialog_content = "I can see that... But you work so late every day, don't you? Surely, you must have saved up a lot of money by now...",
  ui_story_30960401_37_dialog_content = "It's all gone.",
  ui_story_30960401_38_dialog_content = "Due to... uncontrolled demolition and \"unintentional injury.\"",
  ui_story_30960401_39_dialog_content = "How can you say something so outlandish, yet so calmly...",
  ui_story_30960401_40_dialog_content = "How much money do you need? I'll talk to Vice. It shouldn't be too—",
  ui_story_30960401_41_dialog_content = "<color=#FFB400>23,967,500</color> Nightium.",
  ui_story_30960401_42_dialog_content = "...",
  ui_story_30960401_43_dialog_content = "Ha... For a moment there, I thought you said over 20 million... Haha... Wait, how much!?",
  ui_story_30960401_44_dialog_content = "Right, <color=#FFB400><size=45>23,967,500 Nightium</size></color>.",
  ui_story_30960401_45_dialog_content = "...",
  ui_story_30960401_46_dialog_content = "...",
  ui_story_30960401_47_dialog_content = "Sariel, what have you gotten yourself into?",
  ui_story_30960401_48_dialog_content = "No.",
  ui_story_30960401_49_dialog_content = "Are you kidding? Did someone put you up to this?",
  ui_story_30960401_50_dialog_content = "No...",
  ui_story_30960401_51_dialog_content = "Did Kleken send you over here?",
  ui_story_30960401_52_dialog_content = "PlayerName, I'm honestly just asking for your help.",
  ui_story_30960401_53_dialog_content = "Then you'd better start explaining what you need such a huge sum of money for.",
  ui_story_30960401_54_dialog_content = "You know, maybe if I sell Jona's head, I may just be able to get it for you.",
  ui_story_30960401_55_dialog_content = "I need it to buy a ticket.",
  ui_story_30960401_56_dialog_content = "Just one ticket... It's very important to me.",
  ui_story_30960401_57_dialog_content = "Erm... Is it a one-way ticket to \"The Land of Infinite Wealth and Freedom\"?",
  ui_story_30960401_58_dialog_content = "<size=40>Where is that?</size> <size=45>I'd love to visit.</size> <size=50>If I go there, will I become rich... and free?</size>",
  ui_story_30960401_59_dialog_content = "I'm sorry... I forgot that you always take what people say at face value...",
  ui_story_30960401_60_dialog_content = "I'm talking about an airship ticket to Lumopolis.",
  ui_story_30960401_61_dialog_content = "An airship ticket? And that costs over 20 million?",
  ui_story_30960401_62_dialog_content = "Right. It's the passenger airship that runs between Umbraton and Lumopolis every day.",
  ui_story_30960401_63_dialog_content = "You're saying each ticket costs more than 20 million? Who told you that?",
  ui_story_30960401_64_dialog_content = "Kleken.",
  ui_story_30960401_65_dialog_content = "(I know he must have something to do with this...)",
  ui_story_30960401_66_dialog_content = "I calculated that if I carry on working in Umbraton, it'll take me... <color=#FFB400>3,000</color> years or so to make enough money.",
  ui_story_30960401_67_dialog_content = "Hmm... Or was it <color=#FFB400>30,000</color> years? I can't remember. Ah, and the number 3 is so unsightly... Let's change it to an 8...",
  ui_story_30960401_68_dialog_content = "Sariel, a certain saying springs to mind... Though, I'm not sure whether I should say it or not.",
  ui_story_30960401_69_dialog_content = "I don't know either... because I haven't heard it yet.",
  ui_story_30960401_70_dialog_content = "Don't you think the price is totally unrealistic? How would anyone be able to afford a ticket that expensive?",
  ui_story_30960401_71_dialog_content = "...",
  ui_story_30960401_72_dialog_content = "Oh!",
  ui_story_30960401_73_dialog_content = "So that's how it is!",
  ui_story_30960401_74_dialog_content = "(Could it be that... she finally gets it?)",
  ui_story_30960401_75_dialog_content = "The other passengers must have worked <size=45>really, really hard, right</size>?",
  ui_story_30960401_76_dialog_content = "No... They must have worked for a <size=45>really, really long time, right</size>?",
  ui_story_30960401_77_dialog_content = "Sorry, I keep forgetting that you're... somewhat challenged when it comes to common sense...",
  ui_story_30960401_78_dialog_content = "You look like you're mocking me. I'm quite familiar with that look.",
  ui_story_30960401_79_dialog_content = "S-Sorry... But you're so different from most people I've met, Sariel.",
  ui_story_30960401_80_dialog_content = "Really? What do you mean?",
  ui_story_30960401_81_dialog_content = "Wait a minute. Move a little bit to the left first.",
  ui_story_30960401_82_dialog_content = "??",
  ui_story_30960401_83_dialog_content = "You just moved from the midpoint of the wall. It's okay now. You're symmetrical again.",
  ui_story_30960401_84_dialog_content = "So? What's the difference between me and the others?",
  ui_story_30960401_85_dialog_content = "...",
  ui_story_30960401_86_dialog_content = "Sariel, let me see if I can guess something first. Tell me if I'm right:",
  ui_story_30960401_87_dialog_content = "You going to Lumopolis has something to do with Gabriel, doesn't it?",
  ui_story_30960401_88_dialog_content = "...",
  ui_story_30960401_89_dialog_content = "(I guessed correctly?)",
  ui_story_30960401_90_dialog_content = "You... used your psychic abilities?",
  ui_story_30960401_91_dialog_content = "No... It's just obvious.",
  ui_story_30960401_92_dialog_content = "Can you tell me why you're looking for her? Maybe I can help? I mean, in addition to the 20 million...",
  ui_story_30960401_93_dialog_content = "It's about my grandfather.",
  ui_story_30960401_94_dialog_content = "Grandfather?",
  ui_story_30960401_95_dialog_content = "Yes. I'm going to ask Gabriel how he died.",
  ui_story_30960401_96_dialog_content = "Oh... That's... I see...",
  ui_story_30960401_97_dialog_content = "Twelve years ago. No, was it ten years ago? Let's go with the average, eleven years ago.",
  ui_story_30960401_98_dialog_content = "My grandfather, <color=#FFB400>Amos</color>, died in Lumopolis.",
  ui_story_30960401_99_dialog_content = "I was still young back then, and most of my memories of him are hazy, but I remember one thing very clearly.",
  ui_story_30960401_100_dialog_content = "One day, my grandfather suddenly left to go on a long journey. He told me to stay at home, and said he'd be back soon.",
  ui_story_30960401_101_dialog_content = "I heard a name back then—Gabriel. She was the reason my grandfather had to leave home and go to Lumopolis.",
  ui_story_30960401_102_dialog_content = "I didn't know that would be the last time I'd see him.",
  ui_story_30960401_103_dialog_content = "I didn't know that... \"Be a good girl, Sariel,\" would be his last words to me.",
  ui_story_30960401_104_option_content = "I'm sorry for reminding you...",
  ui_story_30960401_105_dialog_content = "Thank you for your concern, PlayerName... But you don't have to apologize.",
  ui_story_30960401_106_dialog_content = "That day is always in my mind. I'll never forget it.",
  ui_story_30960401_107_dialog_content = "That day also left a burning question in my mind—who is Gabriel?",
  ui_story_30960401_108_option_content = "I understand your pain.",
  ui_story_30960401_109_dialog_content = "Well, in a way, you and I are in search of something quite similar.",
  ui_story_30960401_110_dialog_content = "The key to my memories is Gabriel, a girl I've never met.",
  ui_story_30960401_111_dialog_content = "The Angel of Lumopolis, Member of the Guardians, the Girl in the Bird Cage...",
  ui_story_30960401_112_dialog_content = "The stories and rumors, they haven't answered any of my questions, so I have to go and find out for myself.",
  ui_story_30960401_113_dialog_content = "I have to meet her in person and ask her what happened all those years ago. I need to know what happened to my grandfather, Amos.",
  ui_story_30960401_114_dialog_content = "And I need to know... just who she really is.",
  ui_story_30960401_115_dialog_content = "Well, as far as I know, Gabriel's past really doesn't seem that complicated... But of course, I don't know the whole story.",
  ui_story_30960401_116_dialog_content = "Really? But she must know something, right?",
  ui_story_30960401_117_dialog_content = "In Lumopolis, on that floating island... Perhaps there I'll find the answers I've been looking for.",
  ui_story_30960401_118_dialog_content = "...",
  ui_story_30960401_119_dialog_content = "Ah, I do know that my grandfather died in Lumopolis Hospital.",
  ui_story_30960401_120_dialog_content = "A grave injury put him in a coma, never to reawaken.",
  ui_story_30960401_121_dialog_content = "Was he in some kind of accident? And was Gabriel involved?",
  ui_story_30960401_122_dialog_content = "Even the Shadowlord doesn't know any more than that, so I have to go and explore the matter for myself.",
  ui_story_30960401_123_dialog_content = "Anyway, that's why I must find Gabriel.",
  ui_story_30960401_124_dialog_content = "(I have a hunch that the \"all-knowing\" Shadowlord is hiding something...)",
  ui_story_30960401_125_dialog_content = "(And then there's Kleken...)",
  ui_story_30960401_127_dialog_content = "She has no control over her power whatsoever. You know that, don't you?",
  ui_story_30960401_128_dialog_content = "Sariel's two volatile personalities dictate that she must be kept under the Shadowlord's supervision at all times, for safety's sake.",
  ui_story_30960401_130_dialog_content = "Or perhaps—under your supervision, PlayerName?",
  ui_story_30960401_131_dialog_content = "You have many burdens to carry, PlayerName... and a long road ahead.",
  ui_story_30960401_133_dialog_content = "It's all gone...",
  ui_story_30960401_134_dialog_content = "Due to... uncontrolled demolition and \"unintentional injury.\"",
  ui_story_30960401_136_dialog_content = "(That's what that guy must have been thinking.)",
  ui_story_30960401_137_dialog_content = "So...",
  ui_story_30960401_138_dialog_content = "You scared me for a second there.",
  ui_story_30960401_139_dialog_content = "Can you help me?",
  ui_story_30960401_140_dialog_content = "Of course! You're my friend, aren't you? Your problems are my problems.",
  ui_story_30960401_141_dialog_content = "Well...",
  ui_story_30960401_142_dialog_content = "But... I don't have that much money, and the money I do have is with Vice. Every expense has to be accounted for.",
  ui_story_30960401_143_dialog_content = "I understand. Where is Vice?",
  ui_story_30960401_144_dialog_content = "No, no, no! That's not what I meant... Sariel, I can help you to find Gabriel.",
  ui_story_30960401_145_dialog_content = "Oh! That would be good, too!",
  ui_story_30960401_146_dialog_content = "Isn't that what this was all about!? Did you really forget!?",
  ui_story_30960401_147_dialog_content = "When? I can wait here.",
  ui_story_30960401_148_dialog_content = "It doesn't matter how long it takes, I can wait. Ah, no... Actually, I have to go back to Umbraton to sign in...",
  ui_story_30960401_149_dialog_content = "If I sign in at 8:00 in the morning, and then again at 8:00 in the evening, the numbers will match perfectly...",
  ui_story_30960401_150_dialog_content = "Wait... If they're using a 24-hour clock, it'll be 8:00 and 20:00, won't it?",
  ui_story_30960401_151_dialog_content = "Wait for me! I'll be back soon!",
  ui_story_30960401_152_dialog_content = "S-Sariel!?",
  ui_story_30960401_153_dialog_content = "She's already gone...",
  ui_story_30960401_154_dialog_content = "Amos... That was the name of Sariel's grandfather.",
  ui_story_30960401_155_dialog_content = "It's hard to imagine Gabriel being involved in such a sinister mystery...",
  ui_story_30960401_156_dialog_content = "...",
  ui_story_30960401_157_dialog_content = "What exactly happened ten years ago...",
  ui_story_30960601_1_dialog_content = "The weather sure is nice today...",
  ui_story_30960601_2_dialog_content = "<color=#e8d9bb>Thwap!</color>",
  ui_story_30960601_3_dialog_content = "Wh-Where did this piece of paper come from?! It went straight for my face...",
  ui_story_30960601_4_dialog_content = "Hmm? There's something written on it...",
  ui_story_30960601_5_dialog_content = "\"Do you wish to become a better person? Do you wish to be successful?\"",
  ui_story_30960601_6_dialog_content = "\"Then come on down to the Rising Star Agency and sign up today!\"",
  ui_story_30960601_7_dialog_content = "\"With all kinds of classes and teaching styles, we are sure to satisfy your desires for greatness!\"",
  ui_story_30960601_8_dialog_content = "\"Classes start at just 1998, and the instructors will come right to your door for lessons!\"",
  ui_story_30960601_9_dialog_content = "\"Starting now, you too can change your entire life for the better!\"",
  ui_story_30960601_10_dialog_content = "Huh. Sounds kind of interesting.",
  ui_story_30960601_11_dialog_content = "Excuse me, may I come in?",
  ui_story_30960601_12_dialog_content = "Sure.",
  ui_story_30960601_13_dialog_content = "Hello, I am the <color=#FFB400>instructor</color> dispatched by the Rising Star Agency. How do you do?",
  ui_story_30960601_17_dialog_content = "S-Sariel?! Why are you...?",
  ui_story_30960601_18_dialog_content = "*Coughs* I'm, uh... Working for the Rising Star Agency at the moment.",
  ui_story_30960601_19_dialog_content = "This is under the table—the benefits for the job are out of this world!",
  ui_story_30960601_20_dialog_content = "They even give me clothes!",
  ui_story_30960601_21_dialog_content = "That's great, but... Why are you telling me all this?",
  ui_story_30960601_22_dialog_content = "Well, we're not allowed to share any of this information with other people... But because we're so close, I figured I'd tell you about it.",
  ui_story_30960601_23_dialog_content = "This is also my first time teaching a class, so please forgive me if I make a few mistakes here and there.",
  ui_story_30960601_23X_dialog_content = "Okay. Got it.",
  ui_story_30960601_24_dialog_content = "Ahem... Then without further ado, let's get started.",
  ui_story_30960601_25_dialog_content = "The classes you have selected are: \"How to Avoid Conflict with Others,\" \"Secret Techniques: Commanding,\" and \"The Way to Wealth.\"",
  ui_story_30960601_26_dialog_content = "We will begin with our first lesson: How to avoid conflict with others.",
  ui_story_30960601_27_dialog_content = "Before we begin, I would like to ask you a few questions...",
  ui_story_30960601_28_dialog_content = "If someone asked you to join her team, but you didn't really want to join, how would you respond?",
  ui_story_30960601_29_dialog_content = "What does that have to do with conflict?",
  ui_story_30960601_30_dialog_content = "Uh, I'm simply trying to get a better understanding of your personality, so that we can establish a positive method of communication...",
  ui_story_30960601_31_dialog_content = "In any case, what is your answer?",
  ui_story_30960601_32_dialog_content = "A: Thank her for her gracious invitation, and respectfully decline.",
  ui_story_30960601_33_dialog_content = "B: Rudely turn her down.",
  ui_story_30960601_34_dialog_content = "Respectfully decline",
  ui_story_30960601_35_dialog_content = "Oh, I get it... This question is to see if I can take the initiative to avoid potential conflicts, right?",
  ui_story_30960601_36_dialog_content = "Of course I would choose to politely decline after thanking her!",
  ui_story_30960601_37_dialog_content = "Correct. You're quite perceptive, aren't you?",
  ui_story_30960601_38_dialog_content = "Rudely turn her down",
  ui_story_30960601_39_dialog_content = "Well, there was a person who invited me to become an Eclipsite... That was like asking me to join her team, in a way.",
  ui_story_30960601_40_dialog_content = "After that, I did turn her down pretty rudely... And then I defeated her in battle.",
  ui_story_30960601_41_dialog_content = "Well, given the situation... I suppose there is some reason behind that choice of action, right?",
  ui_story_30960601_42_dialog_content = "Now then, next question...",
  ui_story_30960601_43_dialog_content = "If someone took something that belonged to you and refused to give it back, what would you do?",
  ui_story_30960601_44_dialog_content = "A: Politely ask them to explain themselves...",
  ui_story_30960601_45_dialog_content = "Oh! There was someone who stole a component that belonged to the Caelestites...",
  ui_story_30960601_46_dialog_content = "Even though it didn't belong exclusively to me, I couldn't just let it fall into that person's hands.",
  ui_story_30960601_47_dialog_content = "So I choose B! Defeat her, and take back the component!",
  ui_story_30960601_48_dialog_content = "Uh... Your answer is a little outside the box, so let me just check my pamphlet really quickly...",
  ui_story_30960601_49_dialog_content = "Ahem, very well. And do you think that your choice was the right one?",
  ui_story_30960601_50_dialog_content = "No... Things are never quite as simple as you all think.",
  ui_story_30960601_51_dialog_content = "<size=45>They're never that simple!</size>",
  ui_story_30960601_52_dialog_content = "Wh-Why did you have to raise your voice and say that a second time?",
  ui_story_30960601_53_dialog_content = "Because that's what the pamphlet tells us to do.",
  ui_story_30960601_54_dialog_content = "Oh, wait... Our pamphlets tell us to play ads occasionally during lessons. I almost forgot!",
  ui_story_30960601_55_dialog_content = "Huh? Play what, now...?",
  ui_story_30960601_56_dialog_content = "\"Still stuck leading an unsuccessful life?\"",
  ui_story_30960601_57_dialog_content = "\"Still racking your brains on how to improve yourself?\"",
  ui_story_30960601_58_dialog_content = "\"Success isn't a method or a condition, but a state of mind!\"",
  ui_story_30960601_59_dialog_content = "\"Let our special courses guide you to a better life!\"",
  ui_story_30960601_60_dialog_content = "\"Act now, and you can receive a 20% discount on all classes by having your friends sign up, as well!\"",
  ui_story_30960601_61_dialog_content = "...",
  ui_story_30960601_62_dialog_content = "Would you like to sign up?",
  ui_story_30960601_63_dialog_content = "Sign me up for five more classes!",
  ui_story_30960601_64_dialog_content = "If it's for knowledge, I don't mind spending a little extra money.",
  ui_story_30960601_65_dialog_content = "I'm sure Vice will understand, too!",
  ui_story_30960601_66_dialog_content = "Thank you for your patronage! You have no idea how much this helps me!",
  ui_story_30960601_67_dialog_content = "What do you mean?",
  ui_story_30960601_68_dialog_content = "Er, n-nothing! Anyway, we should continue with the lesson...",
  ui_story_30960601_69_dialog_content = "No need",
  ui_story_30960601_70_dialog_content = "I don't have much money lately...",
  ui_story_30960601_71_dialog_content = "But aren't you the famous Navigator?",
  ui_story_30960601_72_dialog_content = "You've got connections, and a Colossus to boot! I'm sure a little money isn't a problem...",
  ui_story_30960601_73_dialog_content = "Well, keeping the Colossus in the air and making sure everyone is comfortable and happy costs money, too...",
  ui_story_30960601_74_dialog_content = "I shouldn't spend any more of it, so let's just continue with the class.",
  ui_story_30960601_75_dialog_content = "Okay, then. I can't make you if you aren't willing to do so... Let's continue, then...",
  ui_story_30960601_76_dialog_content = "Conflict can be divided into many types. Allow me to illustrate this with a drawing.",
  ui_story_30960601_77_dialog_content = "And... Another drawing...",
  ui_story_30960601_78_dialog_content = "And another one... And another one...",
  ui_story_30960601_79_dialog_content = "Uh... Sariel? How many more drawings are you going to make?",
  ui_story_30960601_80_dialog_content = "Hang on! I need to draw one more to make it symmetrical!",
  ui_story_30960601_81_dialog_content = "Oh, I completely forgot that you're all about symmetry...",
  ui_story_30960601_82_dialog_content = "Now that we're talking about it, your socks... Only the right one has a hole in it.",
  ui_story_30960601_83_dialog_content = "What?!",
  ui_story_30960601_84_dialog_content = "One second, let me poke a hole in the left one...",
  ui_story_30960601_85_dialog_content = "Also, they're called stockings, not socks.",
  ui_story_30960601_86_dialog_content = "Forget what they're called, the point is...",
  ui_story_30960601_87_dialog_content = "I never thought you'd ruin your clothes like this just to make them symmetrical.",
  ui_story_30960601_88_dialog_content = "But you already know that asymmetrical things make me feel really uncomfortable!",
  ui_story_30960601_89_dialog_content = "Why do you care so much about symmetry, anyway? To go this far is a bit much, you know...",
  ui_story_30960601_90_dialog_content = "Because symmetry implies balance and stability! Also, solemnity and beauty!",
  ui_story_30960601_91_dialog_content = "I call it the sense of symmetry aesthetics.",
  ui_story_30960601_92_dialog_content = "Did you know?",
  ui_story_30960601_93_dialog_content = "The left sides of our faces aren't one-hundred percent symmetrical with the right sides.",
  ui_story_30960601_94_dialog_content = "But when we look in the mirror, we tend to ignore it.",
  ui_story_30960601_95_dialog_content = "This is because we are born with an innate desire for symmetry...",
  ui_story_30960601_96_dialog_content = "Isn't it just because the difference is too small to notice?",
  ui_story_30960601_97_dialog_content = "Huh? Are you seriously questioning all the research I've done on symmetry aesthetics?",
  ui_story_30960601_98_dialog_content = "Uh... Forget I said anything. But the horns on your head aren't symmetrical, either?",
  ui_story_30960601_99_dialog_content = "Ah! D-Don't bring that up! It's hard enough just trying to forget about it!",
  ui_story_30960601_100_dialog_content = "Let's just get back to the lesson at hand!",
  ui_story_30960601_101_dialog_content = "Alright, then... Could you please explain more about the drawings you made just now?",
  ui_story_30960601_102_dialog_content = "Let me see what the pamphlet says...",
  ui_story_30960601_103_dialog_content = "You don't seem very familiar with your course materials... Can you really teach classes like that?",
  ui_story_30960601_104_dialog_content = "Sorry, the head of the Rising Star Agency put this together for me last-minute, so I'm having a hard time understanding it, too.",
  ui_story_30960601_105_dialog_content = "Seems pretty unreliable to me...",
  ui_story_30960601_107_dialog_content = "Grrr... Why aren't any of these letters aligned with one another?",
  ui_story_30960601_108_dialog_content = "Huh?",
  ui_story_30960601_109_dialog_content = "On the pamphlet, see? The last few rows are completely unaligned!",
  ui_story_30960601_110_dialog_content = "\"'How to Avoid Conflict with Others', Subsection 2:\"",
  ui_story_30960601_111_dialog_content = "\"After the first round of questions, we should have established a positive form of communication with the customer.\"",
  ui_story_30960601_112_dialog_content = "\"At this point, this is our best opportunity to explain our marketing philosophy!\"",
  ui_story_30960601_113_dialog_content = "The letters aren't perfectly aligned, and it's driving me crazy!",
  ui_story_30960601_114_dialog_content = "I think the content of the pamphlet is a lot more concerning than the letters themselves, Sariel!",
  ui_story_30960601_115_dialog_content = "Soroz taught me for seventeen years... And I can tell you, this is not how a class should be taught.",
  ui_story_30960601_116_dialog_content = "Classes should be spaces for sharing and receiving knowledge.",
  ui_story_30960601_117_dialog_content = "It's true, they aren't anything like the lessons I took in the past, either... But maybe this is just the newest method of teaching?",
  ui_story_30960601_118_dialog_content = "They even gave us training, too...",
  ui_story_30960601_119_dialog_content = "What did they train you on?",
  ui_story_30960601_120_dialog_content = "Well, they showed us how to introduce ourselves and our curricula...",
  ui_story_30960601_121_dialog_content = "And how to encourage our customers to stay enrolled in classes... And how to <color=#FFB400>promote even more classes to them</color>...",
  ui_story_30960601_122_dialog_content = "This sounds way too suspicious!",
  ui_story_30960601_123_dialog_content = "If you have any questions, comments, or concerns, feel free to fill out this form.",
  ui_story_30960601_124_dialog_content = "Also, please remember to rank your class experience with me today as highly satisfying!",
  ui_story_30960601_125_dialog_content = "But why? I'm not satisfied at all...",
  ui_story_30960601_126_dialog_content = "Because as long as you do that, I'll be able to reap the full benefits of my job.",
  ui_story_30960601_127_dialog_content = "If you don't, they'll dock my pay instead.",
  ui_story_30960601_128_dialog_content = "I'm virtually broke, and I need these benefits to keep making a living.",
  ui_story_30960601_129_dialog_content = "If they dock my pay...",
  ui_story_30960601_130_dialog_content = "How will I afford to feed myself or my cat...?",
  ui_story_30960601_131_dialog_content = "D-Don't worry. I'll be sure to rate the lesson as highly satisfying!",
  ui_story_30960601_132_dialog_content = "But don't you think it's a little harsh of them to deduct your pay if you don't get the best possible rating?",
  ui_story_30960601_133_dialog_content = "Not to mention all those other... questionable points.",
  ui_story_30960601_134_dialog_content = "There's definitely something wrong with this Rising Star Agency place!",
  ui_story_30960601_135_dialog_content = "Like what?",
  ui_story_30960601_136_dialog_content = "Hang on, let me go ask a few market-savvy people about this...",
  ui_story_30960601_137_dialog_content = "It's a scam, isn't it?",
  ui_story_30960601_138_dialog_content = "Definitely a scam.",
  ui_story_30960601_139_dialog_content = "You've been scammed into working for a shady organization.",
  ui_story_30960601_140_dialog_content = "I can tell this is a <color=#FFB400>multi-level marketing scheme</color> just from looking at it. This isn't something an honest business would do.",
  ui_story_30960601_143_dialog_content = "B-But I already signed a contract with the Rising Star Agency, and paid them a deposit...",
  ui_story_30960601_144_dialog_content = "*Sigh* Don't go looking for work with suspicious places like this!",
  ui_story_30960601_145_dialog_content = "There are all kinds of businesses in Umbraton. Some are legitimate, and some are anything but.",
  ui_story_30960601_146_dialog_content = "You need to keep your eyes open for credible workplaces with solid backgrounds and history!",
  ui_story_30960601_147_dialog_content = "I'll go back and ask the Guild to look into this Rising Star Agency.",
  ui_story_30960601_148_dialog_content = "If you have any signed documents, I suggest you let me see them now.",
  ui_story_30960601_149_dialog_content = "I'm certain the paperwork includes terms and conditions meant to prey on the unsuspecting.",
  ui_story_30960601_150_dialog_content = "Thank you... Thank you so much.",
  ui_story_30960601_151_dialog_content = "If they really are a scam agency, then the money I paid...",
  ui_story_30960601_152_dialog_content = "It was all a waste, wasn't it?!",
  ui_story_30960601_153_dialog_content = "1998 Nightium... All of my hard-earned pocket money...",
  ui_story_30960601_154_dialog_content = "All I wanted was to learn some new and valuable knowledge. I never thought...",
  ui_story_30960601_155_dialog_content = "Don't worry, PlayerName. I still intend to finish teaching your classes.",
  ui_story_30960601_156_dialog_content = "They did give us these pamphlets, but I have my own course materials to use, as well.",
  ui_story_30960601_157_dialog_content = "I read lots of books, just so I could be extra prepared for this. See, I have my own notes, too!",
  ui_story_30960601_158_dialog_content = "Sariel, you...",
  ui_story_30960601_159_dialog_content = "And look! Every single row is perfectly aligned!",
  ui_story_30960601_160_dialog_content = "Is that really the point...?",
  ui_story_30960601_161_dialog_content = "Anyways, I'm done following their pamphlet... So, are you still willing to take my class?",
  ui_story_30960601_162_dialog_content = "Of course!",
  ui_story_30960601_163_dialog_content = "Great, then let's take it from the very beginning.",
  ui_story_30960601_164_dialog_content = "Now, in order to understand conflict, we must first understand its definition.",
  ui_story_30960601_165_dialog_content = "\"The definition of conflict mainly emphasizes the existence and awareness of differences in interests...\"",
  ui_story_30960601_167_dialog_content = "We still have plenty of time in this class, so I'll be sure to elaborate on all of these points carefully.",
  ui_story_30960601_168_dialog_content = "Great! Just how a real class is supposed to be!",
  ui_story_30960601_169_dialog_content = "Heh, what a dutiful student you are, PlayerName...",
  ui_story_30960602_1_dialog_content = "I have great news, PlayerName!",
  ui_story_30960602_2_dialog_content = "I should be able to pay you back for buying me lunch the other day!",
  ui_story_30960602_3_option_content = "Don't worry, it was my treat...",
  ui_story_30960602_4_dialog_content = "That won't do. Grandpa used to say that even sisters should repay each other after borrowing money.",
  ui_story_30960602_5_dialog_content = "Besides, someone gave me a super-lucrative job offer!",
  ui_story_30960602_6_option_content = "Did Lady Sheol offer you a new job?",
  ui_story_30960602_7_dialog_content = "It's a new job, but it's not from her.",
  ui_story_30960602_8_dialog_content = "The location appears to be really high-level too.",
  ui_story_30960602_9_dialog_content = "So, what exactly does the job entail?",
  ui_story_30960602_10_dialog_content = "I was told that even a klutz like me should be able to handle it.",
  ui_story_30960602_11_dialog_content = "All I have to do is sit at a table and play all day.",
  ui_story_30960602_12_dialog_content = "Play?",
  ui_story_30960602_13_dialog_content = "Yep! It's one of those games where they throw a little ball into a spinning wheel with lots of numbers on it.",
  ui_story_30960602_14_dialog_content = "... You mean like a roulette?",
  ui_story_30960602_15_dialog_content = "I'm not sure, but even though I tend to mess things up, playing is something I've always been good at!",
  ui_story_30960602_16_dialog_content = "Wait, so you agreed to do this without even knowing the game?",
  ui_story_30960602_17_dialog_content = "Are you sure you're not getting tricked or something? Lots of scammers tend to appear as the new year approaches...",
  ui_story_30960602_18_dialog_content = "No way! Besides, I've already been scammed last month; what are the odds of it happening twice in two months?",
  ui_story_30960602_19_dialog_content = "I think I should go with you, just to be safe...",
  ui_story_30960602_20_dialog_content = "I'm worried you might get in serious trouble this time.",
  ui_story_30960602_21_dialog_content = "Don't you think you're underestimating me?",
  ui_story_30960602_22_dialog_content = "Still, I don't mind if you come along. After all, the boss says I get paid per day.",
  ui_story_30960602_23_dialog_content = "Once I cash out my wages, I'll be able to pay you back and treat you to a nice meal. It'll even have chicken!",
  ui_story_30960602_24_dialog_content = "<color=#e8d9bb>The next day, after arriving at Sariel's designated location.</color>",
  ui_story_30960602_25_dialog_content = "...",
  ui_story_30960602_26_dialog_content = "Hey there, PlayerName!",
  ui_story_30960602_27_dialog_content = "What's with those clothes...?",
  ui_story_30960602_28_dialog_content = "The boss gave them to me and said they'd keep me from standing out too much.",
  ui_story_30960602_29_dialog_content = "I-I see... They do have a certain underground vibe to them.",
  ui_story_30960602_30_dialog_content = "(What an unbelievable outfit...)",
  ui_story_30960602_31_dialog_content = "But... I really... can't stand them...",
  ui_story_30960602_32_dialog_content = "<color=#e8d9bb>Sariel suffers from obsessive-compulsive disorder, especially when it comes to asymmetrical objects.</color>",
  ui_story_30960602_33_dialog_content = "<color=#e8d9bb>Her condition is so serious that if she has a tear in one stocking, she will tear a hole in the other just to match it.</color>",
  ui_story_30960602_34_dialog_content = "<color=#e8d9bb>I have to say, this outfit she's wearing now is hitting all her sore spots—</color>",
  ui_story_30960602_35_dialog_content = "<color=#e8d9bb>An asymmetrical hair accessory.</color>",
  ui_story_30960602_36_dialog_content = "<color=#e8d9bb>An asymmetrical dress.</color>",
  ui_story_30960602_37_dialog_content = "<color=#e8d9bb>And asymmetrical stockings.</color>",
  ui_story_30960602_38_dialog_content = "Boo-hoo...",
  ui_story_30960602_39_dialog_content = "(She's not really gonna cry, is she...?)",
  ui_story_30960602_40_dialog_content = "Uh, Sariel? Have you brought this up with that scammer... I mean, your boss?",
  ui_story_30960602_41_dialog_content = "I did... but the boss said...",
  ui_story_30960602_42_dialog_content = "You're really complaining about the free clothes I gave you? How pretentious.",
  ui_story_30960602_43_dialog_content = "Did living in Umbraton all those years rob you of your common sense?",
  ui_story_30960602_44_dialog_content = "Loads of people are begging for a sweet gig like this. If you don't want it, I'm sure someone else will take it!",
  ui_story_30960602_45_dialog_content = "Seriously, just take a look at yourself! After all these years, have you actually increased your net worth? Can you really say you've been working hard at all?",
  ui_story_30960602_46_dialog_content = "How do you expect to make money when you're willing to give up over something so trivial?",
  ui_story_30960602_47_dialog_content = "... That's it.",
  ui_story_30960602_48_dialog_content = "That's way out of line!",
  ui_story_30960602_49_dialog_content = "He also said I won't get paid if I don't wear these clothes and I'll have to pay him back if they get torn.",
  ui_story_30960602_50_dialog_content = "So, in spite of everything, you still want to do this job?",
  ui_story_30960602_51_dialog_content = "... I...",
  ui_story_30960602_52_dialog_content = "... I have my reasons for making money, so I want to give it a shot.",
  ui_story_30960602_53_dialog_content = "Thanks for coming with me, by the way. With you around... I think I can handle it a little better...",
  ui_story_30960602_54_dialog_content = "Sariel...",
  ui_story_30960602_55_dialog_content = "(At first I just wanted to make sure she wasn't getting scammed, but now I feel compelled to help her finish her job.)",
  ui_story_30960602_56_dialog_content = "Don't worry, I'll help you out however I can.",
  ui_story_30960602_57_dialog_content = "Boo-hoo... I'm so grateful! I can't imagine what would happen to me without you here!",
  ui_story_30960602_58_dialog_content = "Haha, don't mention it. It's almost time to clock in, right? Let's get going.",
  ui_story_30960602_59_dialog_content = "<color=#e8d9bb>In the underground gaming house.</color>",
  ui_story_30960602_60_dialog_content = "<color=#e8d9bb>The sound of spinning wheels and rolling dice can be heard all throughout the place, as people stare with intent at the cards being flipped at their tables.</color>",
  ui_story_30960602_61_dialog_content = "<color=#e8d9bb>The crowds surrounding the tables cheer and groan as the games continue.</color>",
  ui_story_30960602_62_dialog_content = "(I don't think I'm cut out for a place like this...)",
  ui_story_30960602_63_dialog_content = "(But it's for Sariel, so I have to grit my teeth and bear it!)",
  ui_story_30960602_64_dialog_content = "So, is your boss here too, Sariel?",
  ui_story_30960602_65_dialog_content = "Yes, I just saw him a second ago. He's right over... Huh? Where did he go?",
  ui_story_30960602_66_dialog_content = "I guess it doesn't matter. He gave me this tiny receiver to put in my ear, which I can use it to reach him whenever I need. Oh, he's calling me now!",
  ui_story_30960602_67_dialog_content = "The person next to me? You mean PlayerName? He's here to help me... I mean, he's just a friend.",
  ui_story_30960602_68_dialog_content = "Okay, so first I have to exchange the money you gave me for tokens, then sit at one of those tables...",
  ui_story_30960602_69_dialog_content = "After that, I just pick a number... and hand over my tokens...",
  ui_story_30960602_70_dialog_content = "W-Wait, you're offering all of your tokens?!",
  ui_story_30960602_71_dialog_content = "Oh, is that a bad thing?",
  ui_story_30960602_72_dialog_content = "You're not supposed to go all-in on your first game!",
  ui_story_30960602_73_dialog_content = "Thirty-seven, black. Congratulations, Miss, you won.",
  ui_story_30960602_74_dialog_content = "But he said I won! And look, he gave me a bunch of tokens!",
  ui_story_30960602_75_dialog_content = "How exactly did I win anyway? Was it because I offered the most tokens?",
  ui_story_30960602_76_dialog_content = "Beginner's luck, I suppose... Anyway, don't go all-in like that anymore. Start with one or two tokens and go from there.",
  ui_story_30960602_77_dialog_content = "Okay, you're the boss. After all, you seem to know more about this than I do.",
  ui_story_30960602_78_dialog_content = "I don't really get it either, but one of my friends taught me a few tricks before.",
  ui_story_30960602_79_dialog_content = "(Even though I only learned this stuff to avoid getting cheated, it looks like I can finally put it to good use...)",
  ui_story_30960602_80_dialog_content = "So what exactly does \"all-in\" mean?",
  ui_story_30960602_81_dialog_content = "...",
  ui_story_30960602_82_dialog_content = "Two, red. Congratulations, Miss, you won.",
  ui_story_30960602_83_dialog_content = "Unbelievable...",
  ui_story_30960602_84_dialog_content = "Twenty-five wins in a row! This girl must be Lady Luck herself!",
  ui_story_30960602_85_dialog_content = "We need to get on her level too!",
  ui_story_30960602_86_dialog_content = "Uh, PlayerName? Why's everybody staring at me?",
  ui_story_30960602_87_dialog_content = "This game's not that hard. As long as you offer an even number of tokens, you always win.",
  ui_story_30960602_88_dialog_content = "I'd keep my voice down if I were you. We'd be in trouble if those people heard you after losing so many times.",
  ui_story_30960602_89_dialog_content = "It does seem pretty strange though. You've already won twenty-five times... And by just betting on single numbers, no less.",
  ui_story_30960602_90_dialog_content = "Even with incredible luck, this seems way too improbable. Maybe the gaming house is using you as a shill?",
  ui_story_30960602_91_dialog_content = "What do you mean, a \"shill\"?",
  ui_story_30960602_92_dialog_content = "... Never mind. It'd take too long to explain.",
  ui_story_30960602_93_dialog_content = "Anyway, I can barely hold all of these tokens... I think that should do for now.",
  ui_story_30960602_94_dialog_content = "Huh? It's the boss again...",
  ui_story_30960602_95_dialog_content = "What's that? You want me to keep playing or else I won't get paid? But why...?",
  ui_story_30960602_96_dialog_content = "Your boss wants you to keep going?",
  ui_story_30960602_97_dialog_content = "Well it's not the most honest thing to do, but if that's what he wants from you... I guess it's alright.",
  ui_story_30960602_98_dialog_content = "So what's the point of all this? I'm starting to get bored... And these clothes are driving me nuts...",
  ui_story_30960602_99_dialog_content = "Yaaawn—<size=45>Whoa!</size>",
  ui_story_30960602_100_dialog_content = "Sariel bumps into her mountain of tokens as she stretches her back, but manages to avoid knocking it over by twisting out of the way.",
  ui_story_30960602_101_dialog_content = "Unfortunately, the awkward maneuver causes her to kick her chair away and bump into the table.",
  ui_story_30960602_102_dialog_content = "It takes a certain amount of skill to fall in such a spectacular way.",
  ui_story_30960602_103_dialog_content = "Ouch...",
  ui_story_30960602_104_dialog_content = "... Are you okay? Did you hurt yourself just now?",
  ui_story_30960602_105_dialog_content = "I... I think I pulled a back muscle... It stings pretty badly...",
  ui_story_30960602_106_dialog_content = "No wait, it feels like there's something poking me from under my back.",
  ui_story_30960602_107_dialog_content = "Could you help me pull it out? I can't reach it...",
  ui_story_30960602_108_dialog_content = "... Under your back? I'll try...",
  ui_story_30960602_109_dialog_content = "Ahh...",
  ui_story_30960602_110_dialog_content = "What is it?",
  ui_story_30960602_111_dialog_content = "Nothing, it just felt a lot better when you rubbed my back in that spot...",
  ui_story_30960602_112_dialog_content = "Uh, so where's this thing that's poking you?",
  ui_story_30960602_113_dialog_content = "... Oh, right... I think it's a little lower.",
  ui_story_30960602_114_dialog_content = "... Uh... I don't feel anything down there.",
  ui_story_30960602_115_dialog_content = "No, it's a little lower...",
  ui_story_30960602_116_dialog_content = "Lower...",
  ui_story_30960602_117_dialog_content = "Ah, there it is... Huh? What's this?",
  ui_story_30960602_118_dialog_content = "<size=45>That's mine! Give it back!</size>",
  ui_story_30960602_119_dialog_content = "An old man snatches the object away before anyone can take a clear look at it.",
  ui_story_30960602_120_dialog_content = "Wait... Aren't you one of the players at our table? Sorry, but what's that...",
  ui_story_30960602_121_dialog_content = "<size=45>Stop that man!</size>",
  ui_story_30960602_122_dialog_content = "He has a cheating device in his hands!",
  ui_story_30960602_123_dialog_content = "What? ... Hey, he's trying to run away!",
  ui_story_30960602_124_dialog_content = "<size=45>After him!</size>",
  ui_story_30960602_125_dialog_content = "<size=45>Block the exit! Don't let him get away!</size>",
  ui_story_30960602_126_dialog_content = "<color=#e8d9bb>Thanks to their extremely fast response, the employees quickly apprehend the cheating old man.</color>",
  ui_story_30960602_127_dialog_content = "<color=#e8d9bb>Soon afterward, all of the wins and losses at that table were rendered invalid.</color>",
  ui_story_30960602_128_dialog_content = "<color=#e8d9bb>In other words, the time and effort that Sariel and I spent here was all for nothing.</color>",
  ui_story_30960602_129_dialog_content = "I have to say, this isn't how I expected things to end at all.",
  ui_story_30960602_130_dialog_content = "There goes all my pay... boo-hoo...",
  ui_story_30960602_131_option_content = "Just be grateful you didn't get in trouble.",
  ui_story_30960602_132_option_content = "At least you helped catch a cheater.",
  ui_story_30960602_133_dialog_content = "I can't believe the person who hired you used you like this to cheat and profit afterward.",
  ui_story_30960602_134_dialog_content = "Then again, you probably don't understand anything I just said...",
  ui_story_30960602_135_dialog_content = "Why would he use me to cheat instead of doing it himself?",
  ui_story_30960602_136_dialog_content = "I think he was using you to draw attention away from himself. By making you look like Lady Luck, he'd keep playing without arousing too much suspicion.",
  ui_story_30960602_137_dialog_content = "I bet the clothes he gave you were also meant to draw people's eyes away from him.",
  ui_story_30960602_138_dialog_content = "I see... I still don't get it though.",
  ui_story_30960602_139_dialog_content = "So what should I do about this outfit?",
  ui_story_30960602_140_dialog_content = "No clue. Do you think you should give it back to him even though he's already been arrested?",
  ui_story_30960602_141_dialog_content = "No way. If I do that, I'll really end up with nothing from this job.",
  ui_story_30960602_142_dialog_content = "Besides... It's about time I train myself to handle difficult situations...",
  ui_story_30960602_143_dialog_content = "What do you mean?",
  ui_story_30960602_144_dialog_content = "I spent an entire day wearing these awful clothes, but whenever I started to feel uncomfortable... I thought about you.",
  ui_story_30960602_145_dialog_content = "You... thought about me?",
  ui_story_30960602_146_dialog_content = "Yes. I thought about what you told me, and how you were there to help me.",
  ui_story_30960602_147_dialog_content = "... After that... I didn't feel so uncomfortable.",
  ui_story_30960602_148_dialog_content = "...",
  ui_story_30960602_149_dialog_content = "J-Just like... When you were rubbing my back. It felt just as comfortable.",
  ui_story_30960602_150_dialog_content = "Those are two totally different things! And why do you have to put it like that...?",
  ui_story_30960602_151_dialog_content = "Anyway, I want to train myself to tolerate asymmetrical stuff by wearing this outfit again... Will you help me?",
  ui_story_30960602_152_dialog_content = "(Sariel always comes off as lazy, but...)",
  ui_story_30960602_153_dialog_content = "(... But even she has her serious days, I guess.)",
  ui_story_30960602_154_dialog_content = "Sure, I'd be happy to help!",
  ui_story_30960602_155_dialog_content = "Wear whatever you want, and I'll help you train as long as you need!",
  ui_story_30960602_156_dialog_content = "Heehee, thanks! You really are the greatest person I've ever met in my life.",
  ui_story_30960602_157_dialog_content = "Looks like today wasn't a total bust after all.",
  ui_story_30960602_158_dialog_content = "... Which reminds me, Lady Sheol says to eat a chicken dinner after leaving a gaming house.",
  ui_story_30960602_159_dialog_content = "Do you have any money?",
  ui_story_30960602_160_dialog_content = "I don't...",
  ui_story_30960602_161_dialog_content = "That's fine, it's my treat today.",
  ui_story_30960602_162_dialog_content = "Really?!",
  ui_story_30960602_163_dialog_content = "You really are the best, PlayerName!"
}
return config
